package com.riskguard.transaction.config;
import io.micrometer.core.instrument.MeterRegistry; import io.micrometer.core.instrument.Timer; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter;
@Component public class HttpMetricsFilter extends OncePerRequestFilter { private final MeterRegistry metrics; public HttpMetricsFilter(MeterRegistry metrics){this.metrics=metrics;} @Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{Timer.Sample sample=Timer.start(metrics);try{chain.doFilter(req,res);}finally{metrics.counter("riskguard.http.requests", "method",req.getMethod(),"path",req.getRequestURI(),"status",String.valueOf(res.getStatus())).increment();sample.stop(metrics.timer("riskguard.http.latency","method",req.getMethod(),"path",req.getRequestURI()));}} }
